#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import csv,sys
from pathlib import Path
src,out=map(Path,sys.argv[1:3])
with src.open() as f:deps={r['service']:set() if r['depends']=='-' else set(r['depends'].split(',')) for r in csv.DictReader(f,delimiter='\t')}
if any(d not in deps for ds in deps.values() for d in ds):sys.exit(2)
remaining=set(deps);done=set();waves=[]
while remaining:
    ready=sorted(s for s in remaining if deps[s]<=done)
    if not ready:sys.exit(2)
    waves.append(ready);done.update(ready);remaining.difference_update(ready)
text='step\tservices\n'+''.join(str(i)+'\t'+','.join(names)+'\n' for i,names in enumerate(waves,1))
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(text)
PY
